  const blocks = parseDiffBlocks(diffText);
  if (blocks.length === 0) {
    return { success: false, newContent: originalContent, appliedCount: 0, errors: ["No valid <<<<<<< SEARCH / ======= / >>>>>>> REPLACE blocks found."] };
  }

  let currentContent = originalContent;
  let appliedCount = 0;
  const errors: string[] = [];

