def get_database():
    """Returns indexed documents and metadata for diagnostic inspection."""
    try:
        if not engine.collection:
            return {"error": "Database not initialized", "fixed_chunks": [], "semantic_chunks": []}
        all_docs = engine.collection.get()
        docs = all_docs.get('documents', [])
        metas = all_docs.get('metadatas', [])

        semantic_chunks = []
        for d, m in zip(docs, metas):
            if m and m.get("source"):
                semantic_chunks.append(f"[{m['source']}]\n{d}")
            else:
                semantic_chunks.append(d)

        return {
            "fixed_chunks": engine.docs_texts if engine.docs_texts else [],
            "semantic_chunks": semantic_chunks,
            "count": len(docs)
        }
    except Exception as e:
        return {"error": str(e), "fixed_chunks": [], "semantic_chunks": []}

class SearchEngine:
    def __init__(self):
        self.encoder = None
        self.cross_encoder = None
        self.bm25 = None
        self.docs_texts = []
        self.docs_metas = []
        self.collection = None
        self.ready = False

        self._init_chroma()

    def _init_chroma(self):
        try:
            self.chroma_client = chromadb.PersistentClient(path=str(CHROMA_DB_DIR))
            self.collection = self.chroma_client.get_or_create_collection(name=DEFAULT_COLLECTION_NAME)
        except Exception as e:
            print(f"Warning: Could not initialize Chroma DB at {CHROMA_DB_DIR}: {e}")

    def load_bm25(self):
        if not self.collection:
            return None, [], []
        try:
            all_docs = self.collection.get()
            texts = all_docs.get('documents', [])
            metas = all_docs.get('metadatas', [])
            if not texts:
                return None, [], []
            tokenized_corpus = [doc.lower().split(" ") for doc in texts]
